function applyPlan(m){
 const o=off(m);if(!o.plan||o.planApplied)return false;
 if(o.plan==='recover'){career.health=cap(career.health+15);season(m).fatigue=0}
 else if(o.plan==='skill'){
  if(career.playerId==='custom'){
   /* 自建球员的专项集训直接加属性：潜力线以下 +2，到达/超过潜力只有 +1 且效率很低。 */
   const keys=['finishing','shooting','playmaking','defense','rebounding','athleticism','durability','mentality'];
   let k=o.trainKey;
   if(keys.indexOf(k)<0){
    let best=null,bestGap=-1;
    keys.forEach(x=>{const gap=(Number(career.potentialCaps&&career.potentialCaps[x])||99)-(Number(career.attrs[x])||0);if(gap>bestGap){bestGap=gap;best=x}});
    k=best||'finishing';
   }
   const val=Number(career.attrs[k])||50;
   const pot=Number(career.potentialCaps&&career.potentialCaps[k])||99;
   let gain=0;
   if(val<pot) gain=Math.max(1,Math.min(2,pot-val));
   else if(val<110&&Math.random()<0.5) gain=1;
   if(gain){
    career.attrs[k]=Math.min(110,val+gain);
    career.feed.unshift('专项集训：'+({finishing:'终结',shooting:'投射',playmaking:'组织',defense:'防守',rebounding:'篮板',athleticism:'运动',durability:'耐久',mentality:'心态'}[k]||k)+' +'+gain+(val>=pot?'（已到/超过潜力，效率很低）':'')+'。');
    try{if(typeof syncOvr==='function')syncOvr()}catch(e){}
   }else{
    career.feed.unshift('专项集训：'+({finishing:'终结',shooting:'投射',playmaking:'组织',defense:'防守',rebounding:'篮板',athleticism:'运动',durability:'耐久',mentality:'心态'}[k]||k)+' 已到潜力线，这个夏天没有取得明显突破。');
   }
  }else{
   career.devPoints=(career.devPoints||0)+2;
  }
  career.health=cap(career.health-4);
 }
 else if(o.plan==='chemistry'){m.chemistry=cap(m.chemistry+2,0,5);career.trust=cap(career.trust+4)}
 else{career.trust=cap(career.trust+5);roster(m,career.team).filter(p=>!mine(p)&&p.age<24).forEach(p=>p.ovr=Math.min(p.ceiling,p.ovr+1))}
 o.planApplied=true;powers(m);return true;
}
