function standingsPanel(){const m=ensure();if(!m)return '';function column(c){return '<div class="v73-col"><header><small>'+c+' · 实时战绩</small></header>'+ordered(m,c).map((x,i)=>'<div class="v73-row'+(x.t.abbr===career.team?' me':'')+'"><i>'+(i+1)+'</i>'+(typeof v73Logo==='function'?v73Logo(x.t.abbr):'')+'<b>'+esc(x.t.name)+'</b><span>'+x.w+'</span></div>').join('')+'</div>'}return '<section class="v73-conf"><div class="v73-conf-cols">'+column('东部')+column('西部')+'</div></section>'}
function boardPanel(){
 const m=ensure();if(!m)return '';
 const k=ui.v129Board||'pts',rows=ranking(m,k),self=rows.findIndex(p=>p.self);
 const need=Math.max(k==='mvp'&&career.games>=82?65:1,Math.ceil((Number(career.games)||0)*.70));
 const tabs='<div class="v129-tabs">'+Object.entries(KEYS).map(([v,n])=>button(n,"v129Board('"+v+"')",v===k)).join('')+'</div>';
 if(!rows.length){
  const msg=(Number(career.games)||0)<1
   ? '新赛季还没开打。打满 1 场后，得分、篮板、助攻等榜单会随比赛更新。'
   : '目前还没有球员达到出勤门槛：已赛 '+(Number(career.games)||0)+' 场，至少需要 '+need+' 场。';
  return '<section class="v129-card">'+head('LEAGUE LEADERS','每一场，都在改变排名','其他球员数据与投票为本世界线模拟；场均榜须参加已赛场次的70%。三双按实际单场记录累计，MVP要求90+评分、至少五成胜率及65场出战，综合效率、出勤、球队贡献和连庄表现。')+tabs+'<div class="v129-empty">'+msg+'</div></section>';
 }
 const selected=rows.slice(0,15);if(self>=15)selected.push(rows[self]);
 return '<section class="v129-card">'+head('LEAGUE LEADERS','每一场，都在改变排名','其他球员数据与投票为本世界线模拟；场均榜须参加已赛场次的70%。三双按实际单场记录累计，MVP要求90+评分、至少五成胜率及65场出战，综合效率、出勤、球队贡献和连庄表现。')+tabs+'<div class="v129-list">'+selected.map(p=>'<div class="'+(p.self?'v129-self':'')+'"><strong>'+ (rows.indexOf(p)+1)+'</strong><span><b>'+esc(p.name)+(p.self?' · 你':'')+'</b><small>'+esc(tn(p.team))+' · '+p.gp+'场</small></span><b>'+(['votes','td'].includes(k)?Math.round(p[k]||0).toLocaleString():(p[k]||0).toFixed(1))+'</b></div>').join('')+'</div></section>'
}
function historyPanel(){if(!career)return '';return '<section class="v129-card">'+head('YOUR PLACE IN HISTORY','生涯数据 · 历史位置','与已收录 '+DATA.history.length.toLocaleString()+' 位 NBA/BAA 球员的累计数据快照比较。'+DATA.historyThrough+'；不是5200人完整实时榜，也不是综合历史地位评价。')+'<div class="v129-grid">'+historyRanks().map(r=>'<article><small>'+({points:'总得分',rebounds:'总篮板',assists:'总助攻',steals:'总抢断',blocks:'总盖帽'}[r.key])+'</small><b>第 '+r.rank.toLocaleString()+' 位</b><p>'+r.total.toLocaleString()+' · 随比赛更新</p></article>').join('')+'</div></section>'}
