const oldRegularView=regularView;regularView=function(){return oldRegularView.apply(this,arguments).replace(/<section class="v73-conf">[\s\S]*?<\/section>/g,standingsPanel())};
const oldOff=offseasonView;offseasonView=function(){const m=ensure();if(m&&career.stage==='offseason'&&!window.v141Flow(m).complete)return '<section class="v129-card"><h3>这个夏天，从新的决定开始</h3><p>完成球队运作后，安排个人加点与合同。</p></section>';return oldOff.apply(this,arguments)};
const oldLeague=leagueView;leagueView=function(){const m=ensure();return boardPanel()+(m?'<section class="v129-card">'+head('ROSTER','你的阵容','评分、合同与年龄都随年份变化。')+rosterPanel(m)+'</section>':'')+oldLeague.apply(this,arguments)};
