const oldAwardsView=awardsView;awardsView=function(){
 const m=ensure();if(!m||!season(m).awardSettled)return oldAwardsView.apply(this,arguments);
 const rows=boards(m),eligible=rows.filter(p=>p.gp>=65).sort((a,b)=>b.mvpRaw-a.mvpRaw||a.id.localeCompare(b.id)),def=rows.filter(p=>p.gp>=65).sort((a,b)=>b.def-a.def||a.id.localeCompare(b.id)),rook=rows.filter(p=>(v160Balance.isRookie(m,p))&&p.gp>=50).sort((a,b)=>b.mvp-a.mvp);
 function winner(key){const stat={'得分王':'pts','篮板王':'reb','助攻王':'ast','抢断王':'stl','盖帽王':'blk'}[key];if(stat)return ranking(m,stat).slice(0,1);if(key==='MVP')return eligible.filter(p=>v160Balance.eligible(p,m,true)).sort((a,b)=>b.mvp-a.mvp||a.id.localeCompare(b.id)).slice(0,1);if(key==='DPOY')return def.slice(0,1);if(key==='最佳新秀')return rook.slice(0,1);const nba=['最佳阵容一阵','最佳阵容二阵','最佳阵容三阵'].indexOf(key),defense=['最佳防守一阵','最佳防守二阵'].indexOf(key);return nba>=0?eligible.slice(nba*5,nba*5+5):defense>=0?def.slice(defense*5,defense*5+5):[]}
 let html=oldAwardsView.apply(this,arguments);const parts=html.split('<div class="v35-award ');if(parts.length<2)return html;
 return parts.map((part,i)=>{if(!i)return part;const title=(part.match(/v35-name">([^<]*)</)||[])[1]||'';const award=(career.seasonAwards||[]).find(a=>a.title===title||a.key===title);if(!award)return part;
 const line='<span class="v71-winner">得主：<b>'+(winner(award.key).map(p=>p.self?'你':esc(p.name)).join('、')||'暂无满足参赛门槛的候选')+'</b></span>';
 part=part.replace(/<div class="v67-winner">[\s\S]*?<\/div>/g,'');if(/<span class="v71-winner">/.test(part))return part.replace(/<span class="v71-winner">[\s\S]*?<\/span>/g,line);return part.replace(/(<em class="v35-detail">[\s\S]*?<\/em>)/,'$1'+line);
 }).join('<div class="v35-award ');
};
const oldSave=save;save=function(){const m=ensure();if(m){if(career.stage==='offseason')off(m);normalize(m)}return oldSave.apply(this,arguments)};
window.__v129Debug={ensure,season,phase,profile,annual,boards,ranking,rank,standings,ordered,power,chance,leader,target,makeDraft,draftStep,off,applyPlan,historyRanks,canonical,playGame,roster,payroll,budget,tn,normalize,fillRosters,npcStats,data:DATA};
